"""Author full B1-U02; preserve previous sessions and lexical meanings."""
import json,copy,re,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[4]
KIT=ROOT/'plans/daily-practice-authoring'
OUT=Path(__file__).parent/'packages/B1'
A2=Path(__file__).parent/'packages/A2'
A1=Path(__file__).parent/'packages/A1'
PRE=Path(__file__).parent/'packages/PRE_A1'
level=json.loads((KIT/'levels/B1.plan.json').read_text())['level']
plan=level['units'][1]
W={}
for source in [OUT/'B1-U01.v1.json']+[A2/f'A2-U{n:02}.v1.json' for n in range(20,0,-1)]+[A1/f'A1-U{n:02}.v1.json' for n in range(20,0,-1)]+[PRE/f'PRE_A1-U{n:02}.v1.json' for n in range(20,1,-1)]+[KIT/'examples/PRE_A1-U01.v2.json']:
 for s in json.loads(source.read_text())['sessions']:
  for w in s['vocabulary']:W.setdefault(w['id'],copy.deepcopy(w))
for w in W.values():
 if 'example' not in w:w['example']=dict(fr=w['fr'],ru=w['ru'][0],transcription_ru=w['transcription_ru'])
OLD=set(W);FIRST={};S=[]
U='B1.U02.UNDERSTAND';A='B1.U02.APPLY'
OBJECTIVES={o['id']:o for u in level['units'] for o in u['objectives']}

def ru(t): return dict(text=t,text_lang='ru')

def fr(t,p): return dict(text=t,text_lang='fr',transcription_ru=p)

def ex(f,r,p): return dict(fr=f,ru=r,transcription_ru=p)

def sound(f,p): return dict(text=f,transcription_ru=p,lang='fr-FR',asset_id=None)

def wc(w): return fr(W[w]['fr'],W[w]['transcription_ru'])

def fb(g,b): return dict(correct=g,incorrect=b)

def opts(v): return [dict(id=f'c{i}',**(ru(t) if isinstance(t,str) else t)) for i,t in enumerate(v)]

def rev(i,p,cs,a,g,b): return dict(id=i,type='single_choice',instruction='Выберите один ответ.',prompt=p,choices=opts(cs),correct_choice_id=f'c{a}',feedback=fb(g,b))

def start(n,d,vs):
 p=plan['sessions'][n-1]; s={k:copy.deepcopy(p[k]) for k in ['id','title','order','kind','prerequisite_ids']}
 s.update(version=1,level='B1',unit_id=plan['id'],description=d,duration_minutes=8,objectives=copy.deepcopy(plan['objectives']),skills=[],vocabulary=[copy.deepcopy(W[w]) for w in vs],tasks=[],introductions=[]); S.append(s); return s

def base(s,sk,gs,vs,av,ins,p,g,b):
 for o in gs:
  if o not in [x['id'] for x in s['objectives']]: s['objectives'].append(copy.deepcopy(OBJECTIVES[o]))
 if sk not in s['skills']: s['skills'].append(sk)
 t=dict(id=f'Q{len(s["tasks"])+1:02}',instruction=ins,prompt=p,feedback=fb(g,b),objective_ids=gs,skill=sk,vocabulary_ids=vs,assessed_vocabulary_ids=av); s['tasks'].append(t); return t

def choose(s,sk,gs,vs,av,ins,p,cs,a,g,b):
 t=base(s,sk,gs,vs,av,ins,p,g,b); t.update(type='single_choice',choices=opts(cs),correct_choice_id=f'c{a}'); return t

def listen(s,gs,vs,av,q,f,p,cs,a,g,b):
 return choose(s,'listening',gs,vs,av,'Прослушайте и выберите ответ.',dict(**ru(q),audio=sound(f,p)),cs,a,g,b)

def intro(s,n,t,vs,ns=(),au=None):
 i=dict(id=f'I{len(s["introductions"])+1:02}',before_task_id=f'Q{n:02}',text=t,vocabulary_ids=vs)
 if ns:i['pronunciation_notes']=[dict(fr=f,transcription_ru=p) for f,p in ns]
 if au:i['audio']=sound(*au)
 s['introductions'].append(i)

def pairs(s,gs,rows,g,b):
 vs=[w for w,r in rows]; t=base(s,'vocabulary',gs,vs,vs,'Соедините каждую карточку с её значением.',ru('Используйте все карточки по одному разу.'),g,b)
 t.update(type='matching_pairs',left_items=[dict(id=f'l{i}',**wc(w)) for i,(w,r) in enumerate(rows)],right_items=[dict(id=f'r{i}',**ru(r)) for i,(w,r) in reversed(list(enumerate(rows)))],correct_pairs=[dict(left_id=f'l{i}',right_id=f'r{i}',assessed_vocabulary_ids=[w]) for i,(w,r) in enumerate(rows)])

def order(s,gs,vs,av,ins,ts,f,p,g,b):
 t=base(s,'sentence_building',gs,vs,av,ins,ru('Нажимайте на карточки в нужном порядке.'),g,b); tokens=[dict(id=f't{i}',**fr(f,p)) for i,(f,p) in enumerate(ts)]
 t.update(type='word_order',tokens=list(reversed(tokens)),accepted_orders=[[x['id'] for x in tokens]],completed_phrases=[dict(fr=f,transcription_ru=p)])

def fill(s,gs,vs,av,ins,bef,bp,aft,ap,cs,a,f,p,g,b):
 if aft=='.' and not ap:aft='';f=f.removesuffix('.');p=p.removesuffix('.')
 t=base(s,'vocabulary',gs,vs,av,ins,ru('Выберите одну карточку для пропуска.'),g,b)
 t.update(type='fill_blank',input_mode='choice',text_before=bef,text_before_transcription_ru=bp,text_after=aft,text_after_transcription_ru=ap,choices=opts(cs),correct_choice_id=f'c{a}',completed_phrases=[dict(fr=f,transcription_ru=p)])

 return t

def page(s,blocks):
 s['public_page']=dict(slug=s['id'].lower().replace('_','-'),summary=s['description'],seo_title=s['title']+' — практика французского',seo_description=s['description'],explanation_blocks=[dict(heading=h,paragraphs=ps,examples=es) for h,ps,es in blocks])

def grammar(t):
 t['skill']='grammar'
 return t

def phrase_pairs(s,gs,rows,g,b):
 vs=list(dict.fromkeys(w for f,p,r,ws,av in rows for w in ws)); avs=list(dict.fromkeys(w for f,p,r,ws,av in rows for w in av))
 t=base(s,'vocabulary',gs,vs,avs,'Соедините реплику или выражение с его смыслом.',ru('Используйте каждую карточку один раз.'),g,b)
 t.update(type='matching_pairs',left_items=[dict(id=f'l{i}',**fr(f,p)) for i,(f,p,r,ws,av) in enumerate(rows)],right_items=[dict(id=f'r{i}',**ru(r)) for i,(f,p,r,ws,av) in reversed(list(enumerate(rows)))],correct_pairs=[dict(left_id=f'l{i}',right_id=f'r{i}',assessed_vocabulary_ids=av) for i,(f,p,r,ws,av) in enumerate(rows)])
 return t

def addword(i,key,f,r,p,e,n,reviews):
 W[i]=dict(id=i,lexeme_key=key,fr=f,ru=[r],transcription_ru=p,example=e,review_items=reviews);FIRST[i]=n
def word(i,key,f,r,p,n,example,meaning_choices,meaning_answer,use_prompt,use_choices,use_answer):
 addword(i,key,f,r,p,example,n,[rev(i+'-meaning',fr(f,p),meaning_choices,meaning_answer,'Правильное значение: '+r+'.','Нужно значение «'+r+'»; остальные варианты называют другое.'),rev(i+'-use',ru(use_prompt),[fr(a,b) for a,b in use_choices],use_answer,'Выбран вариант, который сохраняет условие ситуации.','Нужная реплика: '+use_choices[use_answer][0]+'. '+use_prompt)])
word('convenir-de','fr:convenir-de:agree-action','convenir de','договариваться о действии','ко(н)вэни́р дё',1,ex('Nous convenons de nous retrouver vendredi.','Мы договариваемся встретиться в пятницу.','ну ко(н)вэно(н) дё ну рётрувэ ва(н)дрэди́'),['Договариваться о действии','Переносить срок','Испытывать чувство'],0,'Нужно сообщить именно о договорённости встретиться, а не только о личном желании.',[('Je voudrais venir vendredi.','жё вудрэ вэнир ва(н)дрэди́'),('Nous convenons de nous retrouver vendredi.','ну ко(н)вэно(н) дё ну рётрувэ ва(н)дрэди́'),('J’ai éprouvé de la joie.','жэ эпрувэ дё ла жуа́')],1)
word('disponibilite','fr:disponibilite:person-time-availability','la disponibilité','наличие свободного времени у человека','ла диспонибилитэ́',1,ex('La disponibilité de mon frère.','Наличие свободного времени у моего брата.','ла диспонибилитэ дё мо(н) фрэ́р'),['Наличие свободного времени','Крайний срок','Причина опоздания'],0,'Уточните наличие свободного времени у брата, а не стоимость встречи.',[('Je voudrais préciser le tarif.','жё вудрэ прэсизэ лё тари́ф'),('Je voudrais préciser la date.','жё вудрэ прэсизэ ла да́т'),('Je voudrais préciser la disponibilité de mon frère.','жё вудрэ прэсизэ ла диспонибилитэ дё мо(н) фрэ́р')],2)
word('sous-reserve-de','fr:sous-reserve-de:conditional-arrangement','sous réserve de','при условии: оговорка к договорённости','су рэзэрв дё',1,ex('Sous réserve de la disponibilité de mon frère.','При условии, что у моего брата будет свободное время.','су рэзэрв дё ла диспонибилитэ дё мо(н) фрэ́р'),['Без всяких условий','После указанного момента','При условии, с оговоркой'],2,'Договорённость зависит от свободного времени брата. Сохраните эту оговорку.',[('Sous réserve de la disponibilité de mon frère.','су рэзэрв дё ла диспонибилитэ дё мо(н) фрэ́р'),('Grâce à mon frère.','грас а мо(н) фрэ́р'),('Auparavant.','опарава́(н)')],0)
word('echeance','fr:echeance:agreed-deadline','une échéance','крайний срок выполнения','юн эшэа́(н)с',2,ex('L’échéance est vendredi à midi.','Крайний срок — пятница, полдень.','лэшэа(н)с э ва(н)дрэди а миди́'),['Продолжительность ожидания','Крайний срок выполнения','Место встречи'],1,'Нужно назвать крайний срок, а не время встречи или продолжительность.',[('Une échéance.','юн эшэа́(н)с'),('Un rendez-vous.','э(н) ра(н)дэ ву́'),('Un délai.','э(н) дэлэ́')],0)
word('prolonger','fr:prolonger:extend-time-allowance','prolonger','продлевать отведённый срок','проло(н)жэ́',3,ex('Pourriez-vous prolonger le délai ?','Не могли бы вы продлить срок?','пурье ву проло(н)жэ лё дэлэ́'),['Подтверждать встречу','Продлевать отведённый срок','Уточнять место'],1,'Вы просите больше времени на работу, а не просто уточняете дату.',[('Pourriez-vous préciser la date ?','пурье ву прэсизэ ла да́т'),('Pourriez-vous prolonger le délai ?','пурье ву проло(н)жэ лё дэлэ́'),('Je voudrais préciser le lieu.','жё вудрэ прэсизэ лё льё')],1)
word('confirmer','fr:confirmer:confirm-arrangement','confirmer','подтверждать договорённость','ко(н)фирмэ́',4,ex('Je confirme le rendez-vous de samedi.','Я подтверждаю встречу в субботу.','жё ко(н)фирм лё ра(н)дэ ву дё самди́'),['Предлагать перенос','Просить продление','Подтверждать договорённость'],2,'Нужно подтвердить уже согласованную встречу, а не предложить изменение.',[('Je voudrais reporter le rendez-vous.','жё вудрэ рёпортэ лё ра(н)дэ ву́'),('Je confirme le rendez-vous de samedi.','жё ко(н)фирм лё ра(н)дэ ву дё самди́'),('Pourriez-vous prolonger le délai ?','пурье ву проло(н)жэ лё дэлэ́')],1)
for w,g,b in [('convenir-de','Сообщается о совместной договорённости.','Личное желание ещё не означает согласованный план; радость описывает чувство.'),('disponibilite','Уточняется наличие свободного времени у человека.','Дата и цена — другие детали, которые сами по себе не подтверждают доступность.'),('sous-reserve-de','Сохранено условие свободного времени.','Благоприятная причина и предшествование не заменяют условие договорённости.'),('echeance','Назван крайний срок выполнения.','Встреча — событие, а отведённый промежуток времени отличается от его конечной границы.'),('prolonger','Запрошено больше времени на выполнение.','Уточнение даты или места не является просьбой продлить срок.'),('confirmer','Подтверждается уже согласованная встреча.','Предложение переноса и просьба о продлении не подтверждают прежние условия.')]:W[w]['review_items'][1]['feedback']=fb(g,b)
# Avoid an untaught distractor: use a familiar request about the schedule.
W['prolonger']['review_items'][1]['choices'][2].update(text='Je voudrais préciser l’horaire.',transcription_ru='жё вудрэ прэсизэ лорэ́р')

s=start(1,'Отличите предложение от договорённости с условием и от сообщения о будущем действии.',[])
choose(s,'vocabulary',['B1.U01.APPLY'],['grace-a','soeur','auparavant'],['grace-a'],'Входное повторение: какая связка называет полезную причину результата?',ru('Участие сестры помогло приготовить ужин.'),[fr('Auparavant','опарава́(н)'),fr('Grâce à ma sœur','грас а ма сёр'),fr('Ensuite','а(н)сюи́т')],1,'Названа полезная причина, а не время события.','Благодаря моей сестре передаёт её вклад; до этого и затем задают порядок.')
intro(s,2,'Convenir de — договариваться о действии. В выбранной модели Nous convenons de nous retrouver vendredi участники договариваются встретиться в пятницу. La disponibilité — наличие свободного времени. Sous réserve de вводит оговорку: план зависит от названного условия. Это более официальный способ сказать об условии; он не равен безусловному подтверждению.',['convenir-de','disponibilite','sous-reserve-de'],[('Convenir de','ко(н)вэни́р дё'),('Nous convenons de nous retrouver vendredi','ну ко(н)вэно(н) дё ну рётрувэ ва(н)дрэди́'),('La disponibilité','ла диспонибилитэ́'),('Sous réserve de','су рэзэрв дё')])
intro(s,2,'Сравните Je voudrais préparer le dîner — «Я хотел бы приготовить ужин» и Je préparerai le dîner — «Я приготовлю ужин». Первая знакомая форма условного наклонения выражает желание; вторая выбранная форма простого будущего сообщает о будущем действии. Если добавлено si mon frère est disponible, выполнение зависит от свободного времени брата. В показанном условии после si стоит настоящее, а не форма будущего.',['je-voudrais','preparer','si-condition'],[('Je voudrais préparer le dîner','жё вудрэ прэпарэ лё динэ́'),('Je préparerai le dîner','жё прэпарэрэ лё динэ́'),('si mon frère est disponible','си мо(н) фрэр э диспони́бль'),('si','си')])
pairs(s,[U],[('convenir-de','Договариваться о действии'),('disponibilite','Наличие свободного времени'),('sous-reserve-de','При условии, с оговоркой')],'Действие договориться, наличие времени и оговорка различены.','Оговорка ограничивает план; она не подтверждает выполнение условия.')
F1='Je voudrais préparer le dîner avec mon frère vendredi soir. Nous convenons de nous retrouver à la maison, sous réserve de la disponibilité de mon frère. Il travaille vendredi matin. Je voudrais préciser son horaire pour le soir. Je préparerai le dîner à huit heures si mon frère est disponible. Je voudrais lui écrire pour préciser la date et l’heure de notre rendez-vous.'
P1='жё вудрэ прэпарэ лё динэ авэк мо(н) фрэр ва(н)дрэди суа́р. ну ко(н)вэно(н) дё ну рётрувэ а ла мэзо(н), су рэзэрв дё ла диспонибилитэ дё мо(н) фрэ́р. иль травай ва(н)дрэди матэ́(н). жё вудрэ прэсизэ со(н) норэр пур лё суа́р. жё прэпарэрэ лё динэ а юи тёр си мо(н) фрэр э диспони́бль. жё вудрэ люи экрир пур прэсизэ ла дат э лёр дё нотр ра(н)дэ ву́.'
V1=['je-voudrais','preparer','diner','frere','vendredi','soir','convenir-de','retrouver','maison','sous-reserve-de','disponibilite','travailler','matin','preciser','horaire','huit','heure','si-condition','disponible','lui-coi','ecrire','date','rendez-vous']
